        ctl = d2_GetWinObj(win, 1, io_PrintText(0x1981, fame));
        d2_SetObjValue(ctl, 2, 6, 2);
        ok = d2_GetWinObj(win, 1, io_PrintText(0x1982));
        cancel = d2_GetWinObj(win, 1, io_PrintText(0x1983));
