            entfuehren = sv_RegisterNamePlate("contact_ENTFUEHREN", ai_ContactTextKidnap, 0x16);
            loesegeld = sv_RegisterNamePlate("contact_LOESEGELD", ai_ContactTextRansom, 0x16);
