    draw = (int)((float)ai_SettingRandom(rec) * ai_FloatHundred);
    sum = 0;
    pick = 0;
    i = 0;
    p = rec->slots;
    do {
        if (pick != 0)
            return pick;
        if (p->good != 0) {
            sum += p->weight;
            if (p->weight != 0 && draw < sum)
                pick = p->good;
        }
        i++;
        p++;
    } while (i < 7);
    return pick;
