    char text[0x800];
    int i;
    int n;
    int found;

    (void)param_1;
    *(int *)(param_2 + 0x10) = 1;
    gm_Shuffled(5, pick);
    n = 0;
    found = 0;
    for (i = 0; i < 5 && n < 1; i++) {
        if (*(unsigned char *)(param_3 + pick[i] + 0x80) < 0xfc) {
            ai_ApplyTrialStep(param_3, pick[i]);
            found = pick[i];
            n++;
        }
    }
